DROP POLICY IF EXISTS "Allow authenticated full access to physical_inventories" ON public.physical_inventories;
DROP POLICY IF EXISTS "Allow authenticated full access to physical_inventory_items" ON public.physical_inventory_items;
CREATE POLICY "Physical inventories view by store access" ON public.physical_inventories FOR SELECT TO authenticated USING (store_id IS NOT NULL AND (SELECT public.has_store_access(store_id)));
CREATE POLICY "Physical inventories insert by store managers" ON public.physical_inventories FOR INSERT TO authenticated WITH CHECK (store_id IS NOT NULL AND (SELECT public.get_user_store_role(store_id)) IN ('ADMIN','MANAGER') AND created_by = (SELECT auth.uid()));
CREATE POLICY "Physical inventories update by store managers" ON public.physical_inventories FOR UPDATE TO authenticated USING (store_id IS NOT NULL AND (SELECT public.get_user_store_role(store_id)) IN ('ADMIN','MANAGER')) WITH CHECK (store_id IS NOT NULL AND (SELECT public.get_user_store_role(store_id)) IN ('ADMIN','MANAGER'));
CREATE POLICY "Physical inventories delete by store managers" ON public.physical_inventories FOR DELETE TO authenticated USING (store_id IS NOT NULL AND (SELECT public.get_user_store_role(store_id)) IN ('ADMIN','MANAGER'));
CREATE POLICY "Physical inventory items view by inventory store access" ON public.physical_inventory_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.physical_inventories pi WHERE pi.id = inventory_id AND pi.store_id IS NOT NULL AND (SELECT public.has_store_access(pi.store_id))));
CREATE POLICY "Physical inventory items insert by inventory managers" ON public.physical_inventory_items FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.physical_inventories pi WHERE pi.id = inventory_id AND pi.store_id IS NOT NULL AND (SELECT public.get_user_store_role(pi.store_id)) IN ('ADMIN','MANAGER')));
CREATE POLICY "Physical inventory items update by inventory managers" ON public.physical_inventory_items FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.physical_inventories pi WHERE pi.id = inventory_id AND pi.store_id IS NOT NULL AND (SELECT public.get_user_store_role(pi.store_id)) IN ('ADMIN','MANAGER'))) WITH CHECK (EXISTS (SELECT 1 FROM public.physical_inventories pi WHERE pi.id = inventory_id AND pi.store_id IS NOT NULL AND (SELECT public.get_user_store_role(pi.store_id)) IN ('ADMIN','MANAGER')));
CREATE POLICY "Physical inventory items delete by inventory managers" ON public.physical_inventory_items FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.physical_inventories pi WHERE pi.id = inventory_id AND pi.store_id IS NOT NULL AND (SELECT public.get_user_store_role(pi.store_id)) IN ('ADMIN','MANAGER')));